_get_repo_root() {
  local script_file="${BASH_SOURCE[0]:-$0}"
  local script_dir
  script_dir=$(cd "$(dirname "$script_file")" 2>/dev/null && pwd -P || true)
  local root=""
  if [[ -n "$script_dir" && -d "$script_dir" ]]; then
    root=$(git -C "$script_dir" rev-parse --show-toplevel 2>/dev/null || true)
    if [[ -n "$root" ]]; then
      root=$(cd "$root" 2>/dev/null && pwd -P || echo "$root")
    else
      root=$(cd "$script_dir/../.." 2>/dev/null && pwd -P || true)
    fi
  fi
  if [[ -z "$root" ]]; then
    root=$(git rev-parse --show-toplevel 2>/dev/null || pwd -P)
    root=$(cd "$root" 2>/dev/null && pwd -P || echo "$root")
  fi
  printf '%s' "$root"
}

_create_secure_tmp_dir() {
  local repo_root
  repo_root=$(_get_repo_root)
  local safe_base=""
  local candidates=("${TMPDIR:-}" "/tmp" "/var/tmp" "$HOME/.cache" "$HOME/.config" "$HOME")
  for c in "${candidates[@]}"; do
    [[ -n "$c" && -d "$c" ]] || continue
    local canon
    canon=$(cd "$c" 2>/dev/null && pwd -P || true)
    [[ -n "$canon" ]] || continue
    if [[ -n "$repo_root" && ( "$canon" == "$repo_root" || "$canon" == "$repo_root"/* ) ]]; then
      continue
    fi
    safe_base="$canon"
    break
  done
  if [[ -z "$safe_base" ]]; then
    safe_base="/tmp"
  fi
  local res
  res=$(TMPDIR="$safe_base" mktemp -d)
  local canon_res
  canon_res=$(cd "$res" 2>/dev/null && pwd -P || true)
  if [[ -n "$repo_root" && ( "$canon_res" == "$repo_root" || "$canon_res" == "$repo_root"/* ) ]]; then
    rm -rf "$res"
    res=$(TMPDIR="/tmp" mktemp -d)
  fi
  printf '%s' "$res"
}

# State helpers - only non-secret metadata is stored, outside repository root.
is_stage_confirmed() {
  local idx="$1"
  [[ -f "$WIZARD_STATE_FILE" ]] && grep -qE "^STAGE_${idx}_CONFIRMED=true" "$WIZARD_STATE_FILE"
}

confirm_stage() {
  local idx="$1"
  local state_dir
  state_dir=$(dirname "$WIZARD_STATE_FILE")
  [[ -d "$state_dir" ]] || mkdir -p "$state_dir"
  [[ -f "$WIZARD_STATE_FILE" ]] || touch "$WIZARD_STATE_FILE"
  if ! grep -qE "^STAGE_${idx}_CONFIRMED=" "$WIZARD_STATE_FILE"; then
    printf 'STAGE_%s_CONFIRMED=true\n' "$idx" >> "$WIZARD_STATE_FILE"
  fi
}

