  tmp=$(mktemp)
  grep -vE "^${key}=" "$WIZARD_STATE_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "$value" >> "$tmp"
  cat "$tmp" > "$WIZARD_STATE_FILE"
