# Validation helpers under Ley 25.326 data transfer regulations.
validate_vps_region() {
  local reg="$1"
  case "$reg" in
    fsn1|nbg1|[Ff]alkenstein|[Nn]uremberg)
      return 0
      ;;
    *)
      warn "Region '$reg' is refused under Ley 25.326 international data transfer regulations."
      warn "The VPS must be located in Germany (accepted locations: fsn1, nbg1, Falkenstein, Nuremberg)."
      return 1
      ;;
  esac
}

validate_bucket_region() {
  local reg="$1"
  case "$reg" in
    fr-par|[Pp]aris)
      return 0
      ;;
    *)
      warn "Region '$reg' is refused under Ley 25.326 international data transfer regulations."
      warn "The backup bucket must be located in Paris, France (accepted location: fr-par)."
      return 1
      ;;
  esac
}

# Verification helpers: halt on verification failure with guidance.
halt_verification() {
  local stage_num="$1"
  local reason="$2"
  local fix_instruction="$3"
  warn "Verification failed at Stage $stage_num: $reason"
  say "What to fix: $fix_instruction"
  if ! confirm "Would you like to retry the verification check now?"; then
    warn "Stopping wizard at Stage $stage_num. Correct the problem and re-run to resume."
    exit 1
  fi
  return 0
}

check_port_22() {
  local host="$1"
  if command -v ssh >/dev/null 2>&1; then
    local ssh_out=""
    local ssh_rc=0
    ssh_out=$(ssh -o ConnectTimeout=3 -o BatchMode=yes -o StrictHostKeyChecking=accept-new "$host" 2>&1) || ssh_rc=$?
    if [[ $ssh_rc -eq 0 ]]; then
      return 0
    fi
    # Positive evidence of reaching an SSH daemon (rejection or banner from sshd)
    if [[ "$ssh_out" == *"Permission denied"* || \
          "$ssh_out" == *"Host key verification"* || \
          "$ssh_out" == *"remote host identification"* || \
          "$ssh_out" == *"authenticity of host"* || \
          "$ssh_out" == *"SSH-"* ]]; then
      if [[ "$ssh_out" != *"connect to host"* && \
            "$ssh_out" != *"No route to host"* && \
            "$ssh_out" != *"Connection timed out"* && \
            "$ssh_out" != *"Connection refused"* && \
            "$ssh_out" != *"Network is unreachable"* && \
            "$ssh_out" != *"Operation timed out"* && \
            "$ssh_out" != *"Could not resolve"* ]]; then
        return 0
      fi
    fi
    # Indeterminate or connection failure from ssh is treated as failure
  fi
  if command -v nc >/dev/null 2>&1 && nc -z -w 3 "$host" 22 >/dev/null 2>&1; then
    return 0
  fi
  if command -v timeout >/dev/null 2>&1; then
    # shellcheck disable=SC2016
    if timeout 3 bash -c 'exec 3<>/dev/tcp/"$1"/22' _ "$host" 2>/dev/null; then
      return 0
    fi
  fi
  return 1
}

resolve_host_ip() {
  local host="$1"
  local ip=""
  if command -v dig >/dev/null 2>&1; then
    ip=$(dig +short +time=2 +tries=1 "$host" A | tail -n1)
  elif command -v nslookup >/dev/null 2>&1; then
    ip=$(nslookup "$host" 2>/dev/null | awk '/^Address: / { print $2 }' | tail -n1)
  elif command -v getent >/dev/null 2>&1; then
    ip=$(getent ahostsv4 "$host" 2>/dev/null | awk '{ print $1 }' | head -n1)
  elif command -v ping >/dev/null 2>&1; then
    ip=$(ping -c 1 -w 2 "$host" 2>/dev/null | grep -oE '([0-9]{1,3}\.){3}[0-9]{1,3}' | head -n1 || true)
  fi
  printf '%s' "$ip"
}

_get_hetzner_pages() {
  local resource="$1" token="$2" page=1 response next pages=""
  [[ "$resource" == "servers" || "$resource" == "firewalls" ]] || return 1
  command -v curl >/dev/null 2>&1 || return 1
  while (( page <= 10000 )); do
    response=$(printf 'header = "Authorization: Bearer %s"\n' "$token" | curl -fs -K - \
      --connect-timeout 5 --max-time 15 \
      "https://api.hetzner.cloud/v1/${resource}?page=${page}&per_page=50") || return 1
    if command -v node >/dev/null 2>&1; then
      next=$(printf '%s' "$response" | RESOURCE="$resource" PAGE="$page" node -e '
        try {
          const data = JSON.parse(require("fs").readFileSync(0, "utf8"));
          const p = data.meta?.pagination;
          const current = Number(process.env.PAGE);
          if (!Array.isArray(data[process.env.RESOURCE]) || !p || p.page !== current ||
              !Object.prototype.hasOwnProperty.call(p, "next_page")) process.exit(1);
          if (p.next_page === null) process.stdout.write("done");
          else if (Number.isSafeInteger(p.next_page) && p.next_page === current + 1)
            process.stdout.write(String(p.next_page));
          else process.exit(1);
        } catch (e) { process.exit(1); }
      ' 2>/dev/null) || return 1
    elif command -v jq >/dev/null 2>&1; then
      next=$(printf '%s' "$response" | jq -er --arg resource "$resource" --argjson page "$page" '
        if (.[$resource] | type != "array") or (.meta.pagination | type != "object") then error("invalid page")
        elif (.meta.pagination | has("next_page") | not) or (.meta.pagination.page != $page) then error("invalid pagination")
        elif .meta.pagination.next_page == null then "done"
        elif ((.meta.pagination.next_page | type) == "number") and (.meta.pagination.next_page == ($page + 1)) then .meta.pagination.next_page
        else error("invalid next page") end
      ' 2>/dev/null) || return 1
    else
      return 1
    fi
    [[ -z "$pages" ]] || pages+=","
    pages+="$response"
    if [[ "$next" == "done" ]]; then
      printf '{"pages":[%s]}' "$pages"
      return 0
    fi
    page="$next"
  done
  return 1
}

_get_hetzner_server_id() {
  local json="$1"
  local target_ipv4="$2"
  [[ -z "$json" || -z "$target_ipv4" ]] && return 1

  if command -v node >/dev/null 2>&1; then
    local node_code=0
    local s_id=""
    s_id=$(printf '%s' "$json" | TARGET_IP="$target_ipv4" node -e '
      try {
        const data = JSON.parse(require("fs").readFileSync(0, "utf8"));
        const servers = Array.isArray(data.pages) ? data.pages.flatMap(p => p.servers) : data.servers;
        if (!Array.isArray(servers)) process.exit(1);
        const target = process.env.TARGET_IP || "";
        const found = servers.find(s => {
          if (!s) return false;
          const ip = s.public_net?.ipv4?.ip || s.ipv4 || s.ip || (typeof s.public_net?.ipv4 === "string" ? s.public_net.ipv4 : "");
          return ip === target;
        });
        if (found && (found.id !== undefined && found.id !== null)) {
          process.stdout.write(String(found.id));
          process.exit(0);
        }
        process.exit(1);
      } catch (e) {
        process.exit(2);
      }
    ' 2>/dev/null) || node_code=$?
    if [[ $node_code -eq 0 && -n "$s_id" ]]; then
      printf '%s' "$s_id"
      return 0
    fi
    return 1
  fi

  if command -v jq >/dev/null 2>&1; then
    local jq_code=0
    local s_id=""
    s_id=$(printf '%s' "$json" | jq -r --arg ip "$target_ipv4" '
      (if (.pages | type == "array") then [.pages[].servers[]] else .servers end) |
      if type != "array" then
        empty
      else
        .[]? |
        select(
          ((.public_net?.ipv4?.ip == $ip) or (.ipv4 == $ip) or (.ip == $ip) or (.public_net?.ipv4 == $ip)) and
          (.id != null)
        ) |
        .id
      end
    ' 2>/dev/null | head -n1) || jq_code=$?
    if [[ $jq_code -eq 0 && -n "$s_id" && "$s_id" != "null" ]]; then
      printf '%s' "$s_id"
      return 0
    fi
    return 1
  fi

  return 1
}

_verify_hetzner_firewall_response() {
  local json="$1"
  local server_id="${2:-}"
  [[ -z "$json" ]] && return 1

  if command -v node >/dev/null 2>&1; then
    local node_code=0
    printf '%s' "$json" | SERVER_ID="$server_id" node -e '
      try {
        const data = JSON.parse(require("fs").readFileSync(0, "utf8"));
        const firewalls = Array.isArray(data.pages) ? data.pages.flatMap(p => p.firewalls) : data.firewalls;
        if (!Array.isArray(firewalls)) process.exit(1);
        const sId = String(process.env.SERVER_ID || "").trim();
        const allowedPorts = new Set(["22", "80", "443"]);
        if (!sId || firewalls.some(fw => !fw || !Array.isArray(fw.applied_to) ||
            fw.applied_to.some(a => !a || !((a.type === "server" && a.server &&
              (a.server.id != null || typeof a.server === "number" || typeof a.server === "string")) || a.server_id != null)))) process.exit(1);
        const attached = firewalls.filter(fw => fw.applied_to.some(a => {
          if (!a) return false;
          if (a.type === "server" && a.server && String(a.server.id) === sId) return true;
          if (a.type === "server" && String(a.server) === sId) return true;
          return String(a.server_id) === sId;
        }));
        if (!attached.length || attached.some(fw => !Array.isArray(fw.rules) ||
            fw.rules.some(r => !r || !["in", "out"].includes(r.direction)))) process.exit(1);
        const inbound = attached.flatMap(fw => fw.rules.filter(r => r.direction === "in"));
        const ports = new Set();
        const sources = {"80": new Set(), "443": new Set()};
        for (const r of inbound) {
          const p = String(r.port);
          if (r.protocol !== "tcp" || !allowedPorts.has(p) ||
              !Array.isArray(r.source_ips) || !r.source_ips.length ||
              r.source_ips.some(ip => typeof ip !== "string" || !ip)) process.exit(1);
          ports.add(p);
          if (sources[p]) r.source_ips.forEach(ip => sources[p].add(ip));
        }
        const found = ports.size === 3 && ["80", "443"].every(p =>
          sources[p].has("0.0.0.0/0") && sources[p].has("::/0"));
        process.exit(found ? 0 : 1);
      } catch (e) {
        process.exit(2);
      }
    ' >/dev/null 2>&1 || node_code=$?
    if [[ $node_code -eq 0 ]]; then
      return 0
    else
      return 1
    fi
  fi

  if command -v jq >/dev/null 2>&1; then
    local jq_code=0
    printf '%s' "$json" | jq -e --arg sid "$server_id" '
      (if (.pages | type == "array") then {firewalls: [.pages[].firewalls[]]} else . end) |
      if ($sid == "") or (.firewalls | type != "array") or
         (any(.firewalls[]; (type != "object") or (.applied_to | type != "array") or
           any(.applied_to[]; (type != "object") or
             (((.type == "server") and ((.server.id? != null) or ((.server | type) == "number") or ((.server | type) == "string"))) or (.server_id != null) | not)))) then
        false
      else
        [.firewalls[] | select(.applied_to | any(
          ((.type == "server") and ((.server.id? | tostring) == $sid or (.server | tostring) == $sid)) or
          ((.server_id | tostring) == $sid)
        ))] as $attached |
        if ($attached | length == 0) or (any($attached[]; (.rules | type != "array") or
          any(.rules[]; (type != "object") or (.direction != "in" and .direction != "out")))) then
          false
        else
          [$attached[].rules[] | select(.direction == "in")] as $in |
          ($in | all(.protocol == "tcp" and ((.port | tostring) == "22" or (.port | tostring) == "80" or (.port | tostring) == "443") and
            (.source_ips | type == "array") and (.source_ips | length > 0) and
            (.source_ips | all(type == "string" and length > 0)))) and
          ([$in[].port | tostring] | unique | sort == ["22", "443", "80"]) and
          (all("80", "443"; . as $p |
            [$in[] | select((.port | tostring) == $p) | .source_ips[]] as $sources |
            ($sources | index("0.0.0.0/0") != null) and ($sources | index("::/0") != null)))
        end
      end
    ' >/dev/null 2>&1 || jq_code=$?
    if [[ $jq_code -eq 0 ]]; then
      return 0
    else
      return 1
    fi
  fi

  return 1
}

_verify_uptimerobot_response() {
  local json="$1"
  local expected_host="$2"
  local expected_email="${3:-}"
  local target_url="https://${expected_host}/health"
  [[ -z "$json" ]] && return 1

  if command -v node >/dev/null 2>&1; then
    local node_code=0
    TARGET_URL="$target_url" EXPECTED_EMAIL="$expected_email" JSON_STR="$json" node -e '
      try {
        const raw = process.env.JSON_STR || "";
        const data = JSON.parse(raw);
        if (data.stat !== "ok" || !Array.isArray(data.monitors)) {
          process.exit(1);
        }
        const target = process.env.TARGET_URL || "";
        const email = (process.env.EXPECTED_EMAIL || "").toLowerCase().trim();
        const found = data.monitors.some(m => {
          const u = m.url || "";
          const urlMatches = (u === target || u === target + "/");
          const intervalNum = Number(m.interval);
          const intervalMatches = (intervalNum === 300);
          if (!urlMatches || !intervalMatches || ![1, 2, 8, 9].includes(m.status)) return false;

          if (!Array.isArray(m.alert_contacts) || m.alert_contacts.length === 0) {
            return false;
          }
          if (!email) {
            return true;
          }
          return m.alert_contacts.some(c => {
            if (!c) return false;
            if (typeof c === "string") return c.toLowerCase().trim() === email;
            const val = (c.value || c.address || c.email || c.target || "").toLowerCase().trim();
            return val === email;
          });
        });
        process.exit(found ? 0 : 1);
      } catch (e) {
        process.exit(2);
      }
    ' >/dev/null 2>&1 || node_code=$?
    if [[ $node_code -eq 0 ]]; then
      return 0
    else
      return 1
    fi
  fi

  if command -v jq >/dev/null 2>&1; then
    local jq_code=0
    printf '%s' "$json" | jq -e --arg target "$target_url" --arg email "$expected_email" '
      if .stat != "ok" or (.monitors | type != "array") then
        false
      else
        .monitors | any(
          ((.url == $target) or (.url == ($target + "/"))) and
          ((.interval == 300) or (.interval == "300")) and
          (.status == 1 or .status == 2 or .status == 8 or .status == 9) and
          (.alert_contacts | type == "array") and
          ((.alert_contacts | length) > 0) and
          (
            if ($email == "") then
              true
            else
              .alert_contacts | any(
                if type == "string" then
                  (. | ascii_downcase) == ($email | ascii_downcase)
                else
                  ((.value? // .address? // .email? // .target? // "") | ascii_downcase) == ($email | ascii_downcase)
                end
              )
            end
          )
        )
      end
    ' >/dev/null 2>&1 || jq_code=$?
    if [[ $jq_code -eq 0 ]]; then
      return 0
    else
      return 1
    fi
  fi

  return 1
}

run_wizard() {
  # ── Non-interactive modes ───────────────────────────────────────────────────
  if [[ "${1:-}" == "--check" || "${1:-}" == "--dry-run" ]]; then
    printf 'STAGES:\n'
    local i=1
    for t in "${STAGE_TITLES[@]}"; do
      printf '%d. %s\n' "$i" "$t"
      i=$((i + 1))
    done
    printf '\nSECRETS:\n'
    for s in "${CONTRACT_SECRETS[@]}"; do
      printf '%s\n' "$s"
    done
    return 0
  fi

  if [[ "${1:-}" == "--validate-vps-region" ]]; then
    if [[ $# -lt 2 ]]; then
      warn "Missing region argument"
      return 1
    fi
    validate_vps_region "$2"
    return $?
  fi

  if [[ "${1:-}" == "--validate-bucket-region" ]]; then
    if [[ $# -lt 2 ]]; then
      warn "Missing region argument"
      return 1
    fi
    validate_bucket_region "$2"
    return $?
  fi

  # ── Verify required JSON parser exists ──────────────────────────────────────
  if ! _has_json_parser; then
    warn "A JSON parser (node or jq) is required to run the hosting wizard."
    say "Please install jq to continue:"
    say "  • Debian/Ubuntu: sudo apt-get install -y jq"
    say "  • Fedora/RHEL:   sudo dnf install -y jq"
    say "  • Alpine:        apk add jq"
    say "  • Arch Linux:    pacman -S jq"
    say "  • macOS:         brew install jq"
    say "  • Windows:       winget install jqlang.jq"
    exit 1
  fi

  # ── Interactive wizard banner ───────────────────────────────────────────────
  export WIZARD_PID="$$"
  banner "Traslado Programado — Hosting & Infrastructure Wizard"

  # Variables retained across stages in memory
  local HETZNER_REGION="fsn1"
  local HETZNER_IPV4=""
  local DEPLOY_USER="deploy"
  local DOMAIN_NAME=""
  local PRODUCTION_HOST=""
  local STAGING_HOST=""
  local SCW_REGION="fr-par"
  local SCW_BUCKET=""
  local SCW_ACCESS_KEY=""
  local SCW_SECRET_KEY=""
  local ALERT_EMAIL=""

  # Load any previously saved non-secret variables
  HETZNER_IPV4=$(get_state_var HETZNER_IPV4 || true)
  HETZNER_REGION=$(get_state_var HETZNER_REGION || printf 'fsn1')
  DOMAIN_NAME=$(get_state_var DOMAIN_NAME || true)
  PRODUCTION_HOST=$(get_state_var PRODUCTION_HOST || true)
  STAGING_HOST=$(get_state_var STAGING_HOST || true)
  SCW_BUCKET=$(get_state_var SCW_BUCKET || true)

  # ── Stage 1: Hetzner Cloud VPS ─────────────────────────────────────────────
  stage "${STAGE_TITLES[0]}"
  local skip_stage_1=false
  if is_stage_confirmed 1 && [[ -n "$HETZNER_IPV4" ]]; then
    if confirm "Stage 1 already completed (IPv4: $HETZNER_IPV4). Skip to next stage?"; then
      skip_stage_1=true
    fi
  fi

  if [[ "$skip_stage_1" != "true" ]]; then
    say "We will create a CX33 VPS in Germany and capture its public IPv4."
    open_url "https://console.hetzner.cloud"
    step "1. In Hetzner Cloud Console, create or select project 'traslado-programado'."
    step "2. Go to Security ▸ SSH Keys ▸ 'Add SSH key'. Upload your personal public key."
    step "3. Go to Servers ▸ 'Add Server'."
    step "4. Choose Location: Germany (fsn1 Falkenstein or nbg1 Nuremberg)."
    step "5. Image: Ubuntu 24.04 LTS."
    step "6. Type: Standard CX33 (8 GB RAM, 2 vCPU)."
    step "7. Select the SSH key uploaded in step 2."
    step "8. Name the server 'traslado-prod' and click 'Create & Buy now'."

    while true; do
      ask HETZNER_REGION "Enter chosen Hetzner location code [fsn1 or nbg1]:"
      [[ -z "$HETZNER_REGION" ]] && HETZNER_REGION="fsn1"
      if validate_vps_region "$HETZNER_REGION"; then
        case "$HETZNER_REGION" in
          [Ff]alkenstein) HETZNER_REGION="fsn1" ;;
          [Nn]uremberg) HETZNER_REGION="nbg1" ;;
        esac
        break
      fi
    done

    while true; do
      ask HETZNER_IPV4 "Enter the server public IPv4 address:"
      if [[ -z "$HETZNER_IPV4" ]]; then
        warn "IPv4 address is required."
        continue
      fi

      say "Verifying network connectivity to port 22 on $HETZNER_IPV4..."
      if check_port_22 "$HETZNER_IPV4"; then
        note "✓ Port 22 reachable on $HETZNER_IPV4"
        break
      else
        halt_verification 1 \
          "Cannot reach TCP port 22 on $HETZNER_IPV4." \
          "Ensure the server has finished creating in Hetzner Cloud Console and the IP is correct."
      fi
    done

    save_state_var "HETZNER_IPV4" "$HETZNER_IPV4"
    save_state_var "HETZNER_REGION" "$HETZNER_REGION"
    confirm_stage 1
    pause "Stage 1 verified. Press Enter to continue."
  fi

  # ── Stage 2: Hetzner firewall ──────────────────────────────────────────────
  stage "${STAGE_TITLES[1]}"
  local skip_stage_2=false
  if is_stage_confirmed 2; then
    if confirm "Stage 2 already completed. Skip to next stage?"; then
      skip_stage_2=true
    fi
  fi

  if [[ "$skip_stage_2" != "true" ]]; then
    say "We will configure a firewall restricting inbound traffic to ports 22, 80, and 443."
    open_url "https://console.hetzner.cloud"
    step "1. In Hetzner Cloud Console, select project 'traslado-programado' ▸ Firewalls."
    step "2. Click 'Create Firewall' and name it 'traslado-firewall'."
    step "3. Under Inbound Rules, configure exactly:"
    step "   • TCP 22 (SSH) from Any IPv4 / IPv6"
    step "   • TCP 80 (HTTP) from Any IPv4 / IPv6"
    step "   • TCP 443 (HTTPS) from Any IPv4 / IPv6"
    step "4. Remove any other inbound rules."
    step "5. Under 'Apply to', select the server 'traslado-prod' directly, not via a label selector, and click 'Create Firewall'."
    step "6. In Hetzner Cloud Console, go to Security ▸ API Tokens."
    step "   Generate or copy a Read-Only API token to verify the firewall."
    note "The API token is read hidden and passed on stdin to curl; it is never saved to disk."

    local HETZNER_API_TOKEN=""
    while true; do
      ask_secret HETZNER_API_TOKEN "Paste Hetzner Cloud Read-Only API Token:" || true
      if [[ -z "$HETZNER_API_TOKEN" ]]; then
        halt_verification 2 \
          "Hetzner Cloud API Token is required to verify the firewall." \
          "Generate a read-only API token in Hetzner Cloud Console under Security > API Tokens."
        continue
      fi

      if ! _has_json_parser; then
        halt_verification 2 \
          "No JSON parser (node or jq) is available to verify the Hetzner firewall." \
          "Install jq (e.g. apt-get install jq) to enable API verification."
        continue
      fi

      say "Verifying firewall configuration via Hetzner Cloud API..."
      local fw_check_ok=false
      local fw_err=""
      local servers_response=""
      local firewalls_response=""

      servers_response=$(_get_hetzner_pages "servers" "$HETZNER_API_TOKEN" || true)

      local server_id=""
      server_id=$(_get_hetzner_server_id "$servers_response" "$HETZNER_IPV4" || true)

      if [[ -z "$server_id" ]]; then
        fw_err="Server with IPv4 $HETZNER_IPV4 was not found, or the server list could not be verified."
      else
        firewalls_response=$(_get_hetzner_pages "firewalls" "$HETZNER_API_TOKEN" || true)

        if [[ -n "$firewalls_response" ]] && _verify_hetzner_firewall_response "$firewalls_response" "$server_id"; then
          fw_check_ok=true
        else
          fw_err="Firewall is not attached to server ID $server_id (IPv4: $HETZNER_IPV4), pages or attachments could not be verified, or inbound rules are invalid."
        fi
      fi

      if [[ "$fw_check_ok" != "true" ]]; then
        halt_verification 2 \
          "Hetzner firewall verification failed: $fw_err" \
          "Ensure a firewall is attached to the server ($HETZNER_IPV4) with inbound rules allowing only TCP 22, 80, and 443."
        continue
      fi

      say "Verifying SSH port 22 is still reachable through the firewall..."
      if check_port_22 "$HETZNER_IPV4"; then
        note "✓ Hetzner firewall attached and inbound rules verified (TCP 22, 80, 443 only)"
        break
      else
        halt_verification 2 \
          "Cannot reach port 22 on $HETZNER_IPV4." \
          "Ensure the firewall has an inbound rule for TCP 22 and is properly attached to traslado-prod."
      fi
    done

    confirm_stage 2
    pause "Stage 2 verified. Press Enter to continue."
  fi

  # ── Stage 3: Server hardening over SSH ──────────────────────────────────────
  stage "${STAGE_TITLES[2]}"
  local skip_stage_3=false
  if is_stage_confirmed 3; then
    if confirm "Stage 3 already completed. Skip to next stage?"; then
      skip_stage_3=true
    fi
  fi

  if [[ "$skip_stage_3" != "true" ]]; then
    say "We will harden sshd, configure the non-root deploy user, and install Docker."
    step "1. SSH into the server as root: ssh root@$HETZNER_IPV4"
    step "2. Create the deploy user and add to sudoers:"
    step "   adduser --disabled-password --gecos '' deploy"
    step "   usermod -aG sudo deploy"
    step "   echo 'deploy ALL=(ALL) NOPASSWD:ALL' > /etc/sudoers.d/90-deploy"
    step "   mkdir -p /home/deploy/.ssh && cp /root/.ssh/authorized_keys /home/deploy/.ssh/"
    step "   chown -R deploy:deploy /home/deploy/.ssh"
    step "   chmod 700 /home/deploy/.ssh && chmod 600 /home/deploy/.ssh/authorized_keys"
    step "3. Disable password and root login in sshd:"
    step "   echo -e 'PasswordAuthentication no\nPermitRootLogin no' > /etc/ssh/sshd_config.d/00-hardening.conf"
    step "   systemctl restart ssh || systemctl restart sshd"
    step "4. Install Docker Engine and the Compose plugin:"
    step "   curl -fsSL https://get.docker.com | sh"
    step "   usermod -aG docker deploy"

    pause "Press Enter after completing hardening and Docker installation on the server."

    while true; do
      say "Verifying password login is refused on deploy@$HETZNER_IPV4..."
      local ssh_auth_out=""
      if command -v ssh >/dev/null 2>&1; then
        ssh_auth_out=$(ssh -o BatchMode=yes -o PubkeyAuthentication=no -o PreferredAuthentications=none -o ConnectTimeout=5 "deploy@$HETZNER_IPV4" true 2>&1 || true)
      fi

      if [[ "$ssh_auth_out" == *"password"* || "$ssh_auth_out" == *"keyboard-interactive"* ]]; then
        halt_verification 3 \
          "Password login was accepted on deploy@$HETZNER_IPV4!" \
          "Set 'PasswordAuthentication no' and 'PermitRootLogin no' in sshd_config and restart sshd."
        continue
      fi

      if [[ "$ssh_auth_out" != *"Permission denied"* ]]; then
        halt_verification 3 \
          "Could not verify SSH authentication methods on deploy@$HETZNER_IPV4 (SSH response: ${ssh_auth_out:-no response})." \
          "Ensure sshd is running and reachable on port 22, and check network connectivity."
        continue
      fi

      local root_auth_out=""
      if command -v ssh >/dev/null 2>&1; then
        root_auth_out=$(ssh -o BatchMode=yes -o PubkeyAuthentication=no -o PreferredAuthentications=none -o ConnectTimeout=5 "root@$HETZNER_IPV4" true 2>&1 || true)
      fi
      if [[ "$root_auth_out" == *"password"* || "$root_auth_out" == *"keyboard-interactive"* ]]; then
        halt_verification 3 \
          "Root password login was accepted on root@$HETZNER_IPV4!" \
          "Set 'PermitRootLogin no' in /etc/ssh/sshd_config.d/00-hardening.conf and restart sshd."
        continue
      fi

      say "Verifying root login is refused on root@$HETZNER_IPV4..."
      local root_login_ok=false
      local root_login_out=""
      if command -v ssh >/dev/null 2>&1; then
        if root_login_out=$(ssh -o BatchMode=yes -o ConnectTimeout=5 -o StrictHostKeyChecking=accept-new "root@$HETZNER_IPV4" true 2>&1); then
          root_login_ok=true
        fi
      fi

      if [[ "$root_login_ok" == "true" ]]; then
        halt_verification 3 \
          "Root login was accepted on root@$HETZNER_IPV4! Root login must be completely disabled." \
          "Set 'PermitRootLogin no' in /etc/ssh/sshd_config.d/00-hardening.conf and restart sshd."
        continue
      fi

      if [[ "$root_login_out" != *"Permission denied"* ]]; then
        halt_verification 3 \
          "Could not verify that root login is refused on root@$HETZNER_IPV4 (SSH response: ${root_login_out:-no response})." \
          "Ensure sshd is running and reachable on port 22, and check network connectivity."
        continue
      fi

      note "✓ Password login and root login successfully refused"

      say "Verifying SSH key login works for deploy user..."
      local key_login_ok=false
      if command -v ssh >/dev/null 2>&1; then
        if ssh -o BatchMode=yes -o ConnectTimeout=5 -o StrictHostKeyChecking=accept-new "deploy@$HETZNER_IPV4" "docker --version && docker compose version" >/dev/null 2>&1; then
          key_login_ok=true
        fi
      fi

      if [[ "$key_login_ok" == "true" ]]; then
        note "✓ SSH key login and Docker Engine verified for user deploy"
        break
      else
        halt_verification 3 \
          "SSH key login or Docker verification failed on deploy@$HETZNER_IPV4." \
          "Verify /home/deploy/.ssh/authorized_keys and check that docker is running."
      fi
    done

    save_state_var "DEPLOY_USER" "$DEPLOY_USER"
    confirm_stage 3
    pause "Stage 3 verified. Press Enter to continue."
  fi

  # ── Stage 4: GHCR access for the server ────────────────────────────────────
  stage "${STAGE_TITLES[3]}"
  local skip_stage_4=false
  if is_stage_confirmed 4; then
    if confirm "Stage 4 already completed. Skip to next stage?"; then
      skip_stage_4=true
    fi
  fi

  if [[ "$skip_stage_4" != "true" ]]; then
    say "We will authenticate Docker on the server to GitHub Container Registry (ghcr.io)."
    open_url "https://github.com/settings/tokens/new"
    step "1. Generate a Personal Access Token (classic) with note 'traslado-vps-ghcr'."
    step "2. Select ONLY the scope 'read:packages' (do NOT select repo or admin scopes)."
    step "3. Click 'Generate token' and copy it."
    step "4. On your server terminal (logged in as user deploy), run:"
    step "   docker login ghcr.io -u <your-github-username>"
    step "   and paste the token when prompted for password."
    note "The token is typed directly on the server side and is never saved to the repository or locally."

    pause "Press Enter once 'docker login ghcr.io' succeeded on the server."

    while true; do
      say "Verifying GHCR authenticated access on server as user deploy..."
      local ghcr_check_ok=false
      local ghcr_err=""
      local ghcr_out=""
      local test_image="${OSRM_IMAGE:-}"
      if [[ -z "$test_image" ]]; then
        local repo_root
        repo_root=$(_get_repo_root)
        if [[ -n "$repo_root" && -f "$repo_root/compose.yaml" ]]; then
          test_image=$(grep -E '^[[:space:]]*image:[[:space:]]*\$\{OSRM_IMAGE:-' "$repo_root/compose.yaml" 2>/dev/null | sed -E 's/.*:-(.*)\}.*/\1/' || true)
        fi
      fi
      if [[ -z "$test_image" ]]; then
        test_image="ghcr.io/gagaismotuc/traslado-osrm:tucuman-260101-osrm26.4.0-r1"
      fi

      if [[ ! "$test_image" =~ ^(([A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?(\.[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?)*(:[0-9]+)?|\[[0-9a-fA-F:]+\](:[0-9]+)?)/)?([a-z0-9]+(([._]|__|-+)[a-z0-9]+)*/)*[a-z0-9]+(([._]|__|-+)[a-z0-9]+)*(:[A-Za-z0-9_][A-Za-z0-9_.-]{0,127})?(@[A-Za-z][A-Za-z0-9]*([-_+.][A-Za-z][A-Za-z0-9]*)*:[0-9a-fA-F]{32,})?$ ]]; then
        warn "Invalid OSRM_IMAGE: expected a container image reference."
        exit 1
      fi

      if command -v ssh >/dev/null 2>&1; then
        local ssh_rc=0
        ghcr_out=$(ssh -o BatchMode=yes -o ConnectTimeout=10 -o StrictHostKeyChecking=accept-new "deploy@$HETZNER_IPV4" \
          "docker manifest inspect '$test_image' 2>&1 || docker pull '$test_image' 2>&1" 2>&1) || ssh_rc=$?

        if [[ $ssh_rc -eq 0 ]] && echo "$ghcr_out" | grep -qE '"schemaVersion"|"mediaType"|Digest:|Status:|sha256:'; then
          ghcr_check_ok=true
        else
          ghcr_err="${ghcr_out:-empty response from server}"
        fi
      else
        ghcr_err="ssh command not available"
      fi

      if [[ "$ghcr_check_ok" == "true" ]]; then
        note "✓ Authenticated GHCR access verified for user deploy on server"
        break
      else
        halt_verification 4 \
          "GHCR access verification failed on server: $ghcr_err" \
          "Log into server as deploy, run 'docker login ghcr.io' with a PAT having read:packages scope, and retry."
      fi
    done

    confirm_stage 4
    pause "Stage 4 verified. Press Enter to continue."
  fi

  # ── Stage 5: Scaleway Object Storage ───────────────────────────────────────
  stage "${STAGE_TITLES[4]}"
  local skip_stage_5=false
  if is_stage_confirmed 5 && [[ -n "$SCW_BUCKET" ]]; then
    if confirm "Stage 5 already completed (Bucket: $SCW_BUCKET). Skip to next stage?"; then
      skip_stage_5=true
    fi
  fi

  if [[ "$skip_stage_5" != "true" ]]; then
    say "We will create an Object Storage bucket in Paris (fr-par) for off-site encrypted backups."
    open_url "https://console.scaleway.com"
    step "1. In Scaleway Console, create a project or select an existing one."
    step "2. Go to Storage ▸ Object Storage ▸ 'Create bucket'."
    step "3. Set Bucket Name (e.g. 'traslado-programado-backups-prod')."
    step "4. Choose Region: Paris, France (fr-par)."
    step "5. Storage class: Standard (Multi-AZ)."
    step "6. Bucket visibility: Private."
    step "7. Go to IAM ▸ API Keys ▸ 'Generate an API Key'."
    note "Note: Scaleway API keys are scoped to IAM projects and policies. Scope the IAM policy to Object Storage for this project/bucket if available, or to the project."

    while true; do
      ask SCW_REGION "Enter Scaleway bucket region [fr-par]:"
      [[ -z "$SCW_REGION" ]] && SCW_REGION="fr-par"
      if validate_bucket_region "$SCW_REGION"; then
        case "$SCW_REGION" in
          [Pp]aris|fr-par)
            SCW_REGION="fr-par"
            ;;
        esac
        break
      fi
    done

    while true; do
      ask SCW_BUCKET "Enter the created Scaleway bucket name:"
      if [[ -z "$SCW_BUCKET" ]]; then
        warn "Bucket name cannot be empty."
        continue
      fi
      break
    done

    while true; do
      ask_secret SCW_ACCESS_KEY "Paste Scaleway Access Key (starts with SCW):"
      if [[ -z "$SCW_ACCESS_KEY" ]]; then
        warn "Access Key cannot be empty."
        continue
      fi
      break
    done

    while true; do
      ask_secret SCW_SECRET_KEY "Paste Scaleway Secret Key:"
      if [[ -z "$SCW_SECRET_KEY" ]]; then
        warn "Secret Key cannot be empty."
        continue
      fi
      break
    done

    while true; do
      say "Verifying Scaleway Object Storage bucket '$SCW_BUCKET' in region $SCW_REGION..."
      local scw_check_ok=false
      local http_code=""
      if command -v curl >/dev/null 2>&1; then
        http_code=$(printf 'user = "%s:%s"\n' "$SCW_ACCESS_KEY" "$SCW_SECRET_KEY" | curl -s -o /dev/null -w '%{http_code}' --connect-timeout 5 \
          --aws-sigv4 "aws:amz:${SCW_REGION}:s3" \
          -K - \
          "https://${SCW_BUCKET}.s3.${SCW_REGION}.scw.cloud" || true)
        if [[ "$http_code" == "200" ]]; then
          scw_check_ok=true
        fi
      fi

      if [[ "$scw_check_ok" == "true" ]]; then
        note "✓ Scaleway bucket '$SCW_BUCKET' verified in region $SCW_REGION"
        break
      else
        local scw_err_hint="Ensure the bucket exists in Paris ($SCW_REGION) with Private visibility at console.scaleway.com."
        if [[ "$http_code" == "403" ]]; then
          scw_err_hint="Scaleway rejected credentials with HTTP 403 Forbidden. Verify SCW_ACCESS_KEY and SCW_SECRET_KEY have permissions for bucket '$SCW_BUCKET'."
        fi
        halt_verification 5 \
          "Scaleway bucket '$SCW_BUCKET' could not be verified in region $SCW_REGION (HTTP response: ${http_code:-error})." \
          "$scw_err_hint"
      fi
    done

    save_state_var "SCW_BUCKET" "$SCW_BUCKET"
    confirm_stage 5
    note "✓ Scaleway configuration captured in memory (credentials kept off-disk)"
    pause "Stage 5 verified. Press Enter to continue."
  fi

  # ── Stage 6: Domain and DNS ────────────────────────────────────────────────
  stage "${STAGE_TITLES[5]}"
  local skip_stage_6=false
  if is_stage_confirmed 6 && [[ -n "$PRODUCTION_HOST" && -n "$STAGING_HOST" ]]; then
    if confirm "Stage 6 already completed (Prod: $PRODUCTION_HOST, Staging: $STAGING_HOST). Skip to next stage?"; then
      skip_stage_6=true
    fi
  fi

  if [[ "$skip_stage_6" != "true" ]]; then
    say "We will configure DNS A records for production and staging pointing to $HETZNER_IPV4."
    ask DOMAIN_NAME "Enter primary domain (e.g. traslado.example.com or example.com):"
    
    ask PRODUCTION_HOST "Enter production hostname [$DOMAIN_NAME]:"
    [[ -z "$PRODUCTION_HOST" ]] && PRODUCTION_HOST="$DOMAIN_NAME"

    local default_staging="staging.$DOMAIN_NAME"
    ask STAGING_HOST "Enter staging hostname [$default_staging]:"
    [[ -z "$STAGING_HOST" ]] && STAGING_HOST="$default_staging"

    step "1. At your DNS provider/registrar, create an A record:"
    step "   Name/Host: $PRODUCTION_HOST ➔ Points to: $HETZNER_IPV4"
    step "2. Create an A record for staging:"
    step "   Name/Host: $STAGING_HOST ➔ Points to: $HETZNER_IPV4"

    pause "Press Enter after creating DNS A records."

    while true; do
      say "Verifying DNS resolution for $PRODUCTION_HOST and $STAGING_HOST..."
      local prod_ip staging_ip
      prod_ip=$(resolve_host_ip "$PRODUCTION_HOST")
      staging_ip=$(resolve_host_ip "$STAGING_HOST")

      say "  $PRODUCTION_HOST -> ${prod_ip:-not resolved}"
      say "  $STAGING_HOST -> ${staging_ip:-not resolved}"

      if [[ -n "$prod_ip" && "$prod_ip" == "$HETZNER_IPV4" && -n "$staging_ip" && "$staging_ip" == "$HETZNER_IPV4" ]]; then
        note "✓ DNS resolution verified for both hosts"
        break
      else
        halt_verification 6 \
          "DNS did not resolve to $HETZNER_IPV4 (production resolved to '${prod_ip:-none}', staging resolved to '${staging_ip:-none}')." \
          "Check DNS provider records and wait for TTL propagation."
      fi
    done

    save_state_var "DOMAIN_NAME" "$DOMAIN_NAME"
    save_state_var "PRODUCTION_HOST" "$PRODUCTION_HOST"
    save_state_var "STAGING_HOST" "$STAGING_HOST"
    confirm_stage 6
    pause "Stage 6 verified. Press Enter to continue."
  fi

  # ── Stage 7: UptimeRobot ───────────────────────────────────────────────────
  stage "${STAGE_TITLES[6]}"
  local skip_stage_7=false
  if is_stage_confirmed 7; then
    if confirm "Stage 7 already completed. Skip to next stage?"; then
      skip_stage_7=true
    fi
  fi

  if [[ "$skip_stage_7" != "true" ]]; then
    say "We will configure an external HTTPS monitor on UptimeRobot."
    open_url "https://uptimerobot.com/dashboard"
    step "1. In UptimeRobot Dashboard, click '+ Add New Monitor'."
    step "2. Monitor Type: HTTPS."
    step "3. Friendly Name: 'traslado-prod-health'."
    step "4. URL: https://$PRODUCTION_HOST/health"
    step "5. Monitoring Interval: 5 minutes."
    step "6. Alert Contacts: select an email address not hosted on the VPS."

    while true; do
      ask ALERT_EMAIL "Enter the alert notification email address:"
      if [[ -n "$DOMAIN_NAME" && "$ALERT_EMAIL" == *"@$DOMAIN_NAME"* ]]; then
        warn "Alert email must NOT be hosted on the VPS server! Choose an external mailbox (e.g. gmail)."
        continue
      fi
      if [[ -z "$ALERT_EMAIL" ]]; then
        warn "Alert email is required."
        continue
      fi
      break
    done

    step "7. In UptimeRobot Dashboard, go to My Settings ▸ API Settings."
    step "   Create or copy a 'Read-Only API Key' to verify the monitor."
    note "The API key is read hidden and used only in memory to verify the monitor; it is never saved to disk."

    local UPTIMEROBOT_API_KEY=""
    while true; do
      ask_secret UPTIMEROBOT_API_KEY "Paste UptimeRobot Read-Only API Key:" || true
      if [[ -z "$UPTIMEROBOT_API_KEY" ]]; then
        halt_verification 7 \
          "UptimeRobot Read-Only API Key is required to verify the monitor." \
          "Create a Read-Only API Key in UptimeRobot under My Settings > API Settings."
        continue
      fi

      if ! _has_json_parser; then
        halt_verification 7 \
          "No JSON parser (node or jq) is available to verify the UptimeRobot monitor." \
          "Install jq (e.g. apt-get install jq) to enable API verification."
        continue
      fi

      say "Verifying UptimeRobot monitor for https://$PRODUCTION_HOST/health..."
      local monitor_check_ok=false
      local monitor_err=""
      local response=""
      if command -v curl >/dev/null 2>&1; then
        response=$(printf 'data = "api_key=%s&format=json&alert_contacts=1"\n' "$UPTIMEROBOT_API_KEY" | curl -s -X POST \
          -H "Content-Type: application/x-www-form-urlencoded" \
          -H "Cache-Control: no-cache" \
          -K - \
          --connect-timeout 5 \
          "https://api.uptimerobot.com/v2/getMonitors" 2>&1 || true)
      fi

      if [[ -n "$response" ]] && _verify_uptimerobot_response "$response" "$PRODUCTION_HOST" "$ALERT_EMAIL"; then
        monitor_check_ok=true
      else
        monitor_err="No active monitor matching URL https://$PRODUCTION_HOST/health with 5-minute interval and alert contact $ALERT_EMAIL found in UptimeRobot response."
      fi

      if [[ "$monitor_check_ok" == "true" ]]; then
        note "✓ UptimeRobot monitor verified for https://$PRODUCTION_HOST/health (interval: 5 minutes, alert email: $ALERT_EMAIL)"
        break
      else
        halt_verification 7 \
          "UptimeRobot monitor verification failed: $monitor_err" \
          "Ensure the monitor is created at uptimerobot.com with URL https://$PRODUCTION_HOST/health, interval 5 minutes, and alert contact $ALERT_EMAIL."
      fi
    done

    confirm_stage 7
    note "✓ UptimeRobot monitoring configured"
    pause "Stage 7 verified. Press Enter to continue."
  fi

  # ── Stage 8: GitHub secrets for deploy ─────────────────────────────────────
  stage "${STAGE_TITLES[7]}"
  local skip_stage_8=false
  if is_stage_confirmed 8; then
    if confirm "Stage 8 already completed. Skip setting GitHub secrets?"; then
      skip_stage_8=true
    fi
  fi

  if [[ "$skip_stage_8" != "true" ]]; then
    say "We will generate a dedicated deploy SSH key and write the contract secrets to GitHub."

    # Need Scaleway credentials if missing in memory (e.g. resumed session)
    if [[ -z "$SCW_ACCESS_KEY" ]]; then
      ask_secret SCW_ACCESS_KEY "Enter Scaleway Access Key:"
    fi
    if [[ -z "$SCW_SECRET_KEY" ]]; then
      ask_secret SCW_SECRET_KEY "Enter Scaleway Secret Key:"
    fi

    # Generate dedicated deploy SSH keypair in isolated temporary directory outside repo
    WIZARD_TMP_DIR=$(_create_secure_tmp_dir)
    chmod 700 "$WIZARD_TMP_DIR"
    local deploy_key_file="$WIZARD_TMP_DIR/deploy_id_ed25519"
    ssh-keygen -t ed25519 -N "" -f "$deploy_key_file" -C "github-actions-deploy" >/dev/null 2>&1
    local deploy_pub_key
    deploy_pub_key=$(cat "${deploy_key_file}.pub")
    note "The dedicated deploy key is held in a secure directory outside the repo and will be shredded upon completion or interruption; avoid abrupt termination."

    step "Add this dedicated deploy public key to /home/deploy/.ssh/authorized_keys on the server:"
    printf '\n  %s%s%s\n\n' "$BOLD" "$deploy_pub_key" "$RESET"
    step "Command on server: echo '$deploy_pub_key' >> /home/deploy/.ssh/authorized_keys"

    pause "Press Enter once the public key has been added to the server's authorized_keys."

    while true; do
      say "Verifying dedicated deploy SSH key authentication on deploy@$HETZNER_IPV4..."
      local key_auth_ok=false
      local key_auth_out=""
      if command -v ssh >/dev/null 2>&1; then
        if key_auth_out=$(ssh -i "$deploy_key_file" -o IdentitiesOnly=yes -o BatchMode=yes -o ConnectTimeout=5 -o StrictHostKeyChecking=accept-new "deploy@$HETZNER_IPV4" true 2>&1); then
          key_auth_ok=true
        fi
      fi

      if [[ "$key_auth_ok" == "true" ]]; then
        note "✓ Dedicated deploy SSH key verified on server"
        break
      else
        halt_verification 8 \
          "Server rejected authentication with the new dedicated deploy SSH key (response: ${key_auth_out:-no response})." \
          "Ensure the public key is appended to /home/deploy/.ssh/authorized_keys on the server."
      fi
    done

    say "Gathering SSH host keys for DEPLOY_KNOWN_HOSTS via ssh-keyscan..."
    local deploy_known_hosts=""
    if command -v ssh-keyscan >/dev/null 2>&1; then
      deploy_known_hosts=$(ssh-keyscan -H "$HETZNER_IPV4" 2>/dev/null || true)
    fi
    if [[ -z "$deploy_known_hosts" ]]; then
      warn "ssh-keyscan could not fetch keys automatically."
      ask deploy_known_hosts "Paste server ssh-keyscan output for DEPLOY_KNOWN_HOSTS:"
    fi

    local deploy_private_key
    deploy_private_key=$(cat "$deploy_key_file")
    # Shred the private key from temporary disk immediately
    rm -rf "$WIZARD_TMP_DIR"
    WIZARD_TMP_DIR=""

    while true; do
      say "Writing contract secrets to GitHub repository via 'gh secret set'..."
      local failed_writes=()
      set_secret "DEPLOY_HOST" "$HETZNER_IPV4" || failed_writes+=("DEPLOY_HOST")
      set_secret "DEPLOY_USER" "$DEPLOY_USER" || failed_writes+=("DEPLOY_USER")
      set_secret "DEPLOY_SSH_KEY" "$deploy_private_key" || failed_writes+=("DEPLOY_SSH_KEY")
      set_secret "DEPLOY_KNOWN_HOSTS" "$deploy_known_hosts" || failed_writes+=("DEPLOY_KNOWN_HOSTS")
      set_secret "PRODUCTION_HOST" "$PRODUCTION_HOST" || failed_writes+=("PRODUCTION_HOST")
      set_secret "STAGING_HOST" "$STAGING_HOST" || failed_writes+=("STAGING_HOST")
      set_secret "SCW_ACCESS_KEY" "$SCW_ACCESS_KEY" || failed_writes+=("SCW_ACCESS_KEY")
      set_secret "SCW_SECRET_KEY" "$SCW_SECRET_KEY" || failed_writes+=("SCW_SECRET_KEY")
      set_secret "SCW_BUCKET" "$SCW_BUCKET" || failed_writes+=("SCW_BUCKET")

      if (( ${#failed_writes[@]} > 0 )); then
        halt_verification 8 \
          "Failed to write GitHub secrets: ${failed_writes[*]}" \
          "Ensure gh CLI is authenticated with repository write access, then retry."
        continue
      fi

      say "Verifying secrets exist in repository via 'gh secret list'..."
      local gh_secrets
      gh_secrets=$(gh secret list 2>/dev/null || true)
      local missing_secrets=()
      for s in "${CONTRACT_SECRETS[@]}"; do
        if ! echo "$gh_secrets" | grep -qE "(^|[[:space:]])${s}([[:space:]]|$)"; then
          missing_secrets+=("$s")
        fi
      done

      if (( ${#missing_secrets[@]} == 0 )); then
        note "✓ All ${#CONTRACT_SECRETS[@]} contract secrets verified in repository"
        break
      else
        halt_verification 8 \
          "Missing GitHub secrets: ${missing_secrets[*]}" \
          "Ensure gh CLI is authenticated with repository write access, then retry."
        continue
      fi
    done

    confirm_stage 8
    pause "Stage 8 verified. Press Enter to continue."
  fi

  # ── Stage 9: Summary ───────────────────────────────────────────────────────
  stage "${STAGE_TITLES[8]}"
  say "Infrastructure and account provisioning is complete!"
  printf '\n%sResources Created:%s\n' "$BOLD" "$RESET"
  say "• Hetzner CX33 VPS: $HETZNER_IPV4 in Germany ($HETZNER_REGION)"
  say "• Hetzner Firewall: TCP 22, 80, 443 inbound attached to server"
  say "• Server Hardening: non-root user '$DEPLOY_USER', password login disabled, Docker + Compose installed"
  say "• GHCR Authentication: ghcr.io configured for private package access"
  say "• Scaleway Object Storage: bucket '$SCW_BUCKET' in Paris (fr-par)"
  say "• DNS: A records for '$PRODUCTION_HOST' and '$STAGING_HOST' -> $HETZNER_IPV4"
  say "• UptimeRobot: 5-minute health monitor for https://$PRODUCTION_HOST/health"

  printf '\n%sGitHub Secrets Set (Contract #36/#37):%s\n' "$BOLD" "$RESET"
  for s in "${CONTRACT_SECRETS[@]}"; do
    say "  ✓ $s"
  done

  printf '\n%sHandoff to #36 and #37:%s\n' "$BOLD" "$RESET"
  say "• Issue #36 (Deployment): GitHub Actions can deploy via SSH using DEPLOY_HOST, DEPLOY_USER,"
  say "  DEPLOY_SSH_KEY, and DEPLOY_KNOWN_HOSTS, configuring Caddy for PRODUCTION_HOST & STAGING_HOST."
  say "• Issue #37 (Backups): Backup workflows can store encrypted database dumps in SCW_BUCKET"
  say "  using SCW_ACCESS_KEY and SCW_SECRET_KEY in region fr-par."

  confirm_stage 9
  finish
}

run_wizard "$@"; exit
